import{z as s,x as d,o as t,c as A,q as i,j as l,D as o,d as r,s as p,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Dropout 直觉","description":"","frontmatter":{"title":"Dropout 直觉","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dropout-intuition.md","filePath":"llm/dropout-intuition.md","lastUpdated":1791413859000}'),u={name:"llm/dropout-intuition.md"};function B(D,a,m,h,_,c){const E=d("Mermaid");return t(),A("div",null,[a[2]||(a[2]=i('<h1 id="dropout-直觉" tabindex="-1">Dropout 直觉 <a class="header-anchor" href="#dropout-直觉" aria-label="Permalink to &quot;Dropout 直觉&quot;">​</a></h1><div class="epigraph"><p>训练时随机关掉一部分单元，迫使表示不要把预测押在少数共适应的坐标上；推理时用全体，并按保留率缩放。</p><footer>—— 据 Srivastava, Hinton, Krizhevsky, Sutskever &amp; Salakhutdinov, Dropout, JMLR 2014 整理</footer></div><p><a href="/llm/why-layernorm">LayerNorm 的动机</a>管尺度。本课不重写 \\(\\mu,\\sigma\\)。缺口是：尺度稳定之后，网络仍可把全部容量用来记训练样本。权重衰减拉范数，早停切时间；Dropout 在前向上注入噪声，让单元不能互相绑定成死记硬背的电路。本课只讲直觉与训练 / 推理协议。注意力里的 dropout 是同一算子换位置，不在这里提前写成 SDPA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>过拟合课给出 \\(\\lambda\\) 与早停。深度网里还有一种共适应：某些单元只有在另一些单元同时开时才有意义，像在记训练集里的特定搭配。验证集上搭配一变，电路失效。缺口是训练期的扰动：以概率 \\(p\\) 把单元置零（保留率 \\(q=1-p\\)），其余放大 \\(1/q\\)，使期望与推理时全体开启一致。这不是数据增强的同义词——扰动发生在表示上，不发生在输入句子的改写上。</p><p><span class="marginnote">「共适应」就是两个神经元绑成固定搭子：A 只有在 B 同时开时才有用，单独看谁都可有可无，合起来却在背题。Dropout 每次随机「开除」一部分单元，逼每个单元都能独立干活、互相多备几套方案，验证集上搭配一变也不至于全盘失效。</span></p><p>推理必须关掉随机性，否则同一句每次损失不同，也无法部署。inverted dropout 把缩放放在训练侧，推理直接全开。把缩放放在推理侧也可以，但容易忘。本课默认训练缩放。</p><h3 id="dropout-不是注意力掩码" tabindex="-1">Dropout 不是注意力掩码 <a class="header-anchor" href="#dropout-不是注意力掩码" aria-label="Permalink to &quot;Dropout 不是注意力掩码&quot;">​</a></h3><p>注意力掩码按位置把非法键的分数打成 \\(-\\infty\\)，是确定性的结构约束。Dropout 按单元或按注意力权重随机置零，是正则。两者都可以表现为「乘零」，语义完全不同。不要在实现里用同一张 mask 张量既当因果掩码又当 dropout，除非明确是两项相乘。本课的对象是前馈单元与一般激活；序列位置上的 dropout 同理，仍不是因果性。</p><p><span class="marginnote">期望：若训练时 \\(\\tilde h=m\\odot h/q\\)，\\(\\mathbb{E}[m_i]=q\\)，则 \\(\\mathbb{E}[\\tilde h]=h\\)。推理用 \\(h\\)。这是线性期望，对后续非线性只是近似；实践上够用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对激活 \\(h\\)，采样 Bernoulli 掩码 \\(m\\)，正向 \\(\\tilde h=m\\odot h/q\\)。反向梯度同样乘 \\(m/q\\)。嵌入、残差流、MLP 中间层都可以丢；过大的 \\(p\\) 等于减少有效宽度。验证与测试：\\(p=0\\)。与 LayerNorm 共存时，通常在 LN 之后、子层内部丢，避免把噪声写进统计量之前——具体顺序随实现，写结构时要固定。</p><p><span class="marginnote">数字实例：保留率 \\(q=0.9\\) 时，每个激活有 10% 的概率被置零，留下的都乘 \\(1/0.9\\approx 1.11\\)，100 个激活的期望总和与不丢时一致。若忘了除以 \\(q\\)，训练时激活期望只有推理的九成，全体信号被静默缩小，深网会莫名难训。</span></p>',13)),(t(),l(n,null,{default:o(()=>[p(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E6%BF%80%E6%B4%BB%20h%22%5D%20--%3E%20M%5B%22Bernoulli%20%E6%8E%A9%E7%A0%81%22%5D%0A%20%20M%20--%3E%20SCALE%5B%22%E9%99%A4%E4%BB%A5%E4%BF%9D%E7%95%99%E7%8E%87%22%5D%0A%20%20SCALE%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%E7%94%A8%E6%89%B0%E5%8A%A8%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20H%20--%3E%20EVAL%5B%22%E6%8E%A8%E7%90%86%E7%94%A8%E5%85%A8%E4%BD%93%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"Srivastava 等人把 Dropout 解释成指数多种子网络的近似集成：每次随机掩码定义一个瘦网络，参数共享。推理的全开近似几何平均。另一种读法是：噪声让特征必须冗余，单个坐标不能成为唯一线索。两种读法都不需要在本课写成定理。效果上，Dropout 往往抬高训练损失、降低验证缺口，与「更强的优化」方向相反——若训练损失降得很痛快而验证变差，加大 \\(p\\) 是合法杠杆。",-1)),(t(),l(n,null,{default:o(()=>[p(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20DO%5B%22Dropout%22%5D%20--%3E%20R1%5B%22%E6%89%B0%E5%8A%A8%E6%BF%80%E6%B4%BB%3Cbr%3E%E7%BA%A6%E6%9D%9F%E5%8D%95%E6%AC%A1%E5%89%8D%E5%90%91%E7%94%B5%E8%B7%AF%22%5D%0A%20%20WD%5B%22%E6%9D%83%E9%87%8D%E8%A1%B0%E5%87%8F%22%5D%20--%3E%20R2%5B%22%E6%8B%89%E5%B0%8F%E6%9D%83%E9%87%8D%E8%8C%83%E6%95%B0%3Cbr%3E%E7%BA%A6%E6%9D%9F%E5%8F%AF%E8%BE%BE%E5%8F%82%E6%95%B0%E9%9B%86%E5%90%88%22%5D%0A%20%20BN%5B%22%E5%B0%8F%E6%89%B9%E9%87%8F%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20R3%5B%22%E5%9C%A8%E6%A0%B7%E6%9C%AC%E7%BB%B4%E6%8A%96%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20R1%20--%3E%20E%5B%22%E8%AE%AD%E7%BB%83%E6%8D%9F%E5%A4%B1%E7%95%A5%E5%8D%87%3Cbr%3E%E9%AA%8C%E8%AF%81%E7%BC%BA%E5%8F%A3%E5%8F%98%E5%B0%8F%22%5D%0A%20%20R2%20--%3E%20E%0A%20%20R3%20--%3E%20E%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">直觉类比：「指数多种子网络集成」可以想成每天随机让一部分员工放假、公司仍要照常运转，于是每个岗位都练出替补；推理时全员到岗，整体表现接近无数种「放假方案」的平均，而不是任何单一配置。</span></p><p>与权重衰减不同，Dropout 不直接拉 \\(\\|\\theta\\|_2\\)，它改的是前向的有效电路。两者可叠加：衰减约束可达集合，Dropout 约束单次前向能用哪些单元。与小批量噪声也不同：批量噪声在样本维上抖梯度，Dropout 在表示维上抖激活。调 \\(p\\) 时不要把它当成另一种 \\(\\eta\\)。</p><p>小数据、大模型时 \\(p\\) 更大；海量预训练时许多现代网络把 Dropout 降到很小甚至关掉，改用数据本身当正则。本课不把某一 \\(p\\) 奉为常数。残差流上过大的 Dropout 会破坏恒等支路的尺度，实践中常只在 \\(f\\) 内部丢。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进入词向量；下一课起是「序列与注意力之前」的第一课<a href="/llm/distributional-hypothesis">词向量与分布假设</a>。后课默认：训练与推理的 Dropout 开关必须分开；它是正则，不是掩码语义。不要与量化金融或权重量化混淆——本课的「丢」是单元，不是权重比特。DropConnect 改丢权重边，本课不切换。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Dropout 训练时随机置零并缩放，打破共适应；推理全开。</li><li>它是表示噪声正则，不是注意力的因果掩码。</li><li>期望在线性上对齐训练与推理；非线性下只是近似。</li><li>预训练数据极大时可以减弱，小数据过拟合时再加大。</li><li>它改前向电路，不是另一种学习率，也不是权重衰减。</li><li>出处：Srivastava et al., JMLR 2014。</li></ul>',7))])}const q=s(u,[["render",B]]);export{b as __pageData,q as default};
